
(()=>{'use strict';
const ICONS={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',dumbbell:'<path d="M7 12h10M7 7v10M4 9v6M17 7v10M20 9v6M2 12h2m16 0h2"/>',food:'<path d="M4 3v7a3 3 0 0 0 6 0V3M7 3v18M17 3c-2.4 2.5-3.5 6.5-3.5 10h5V3H17Zm1.5 10v8"/>',chart:'<path d="M3 3v18h18M7 17v-5m5 5V7m5 10v-8"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a2 2 0 0 0 .4 2.2l-2.6 2.6A2 2 0 0 0 15 19.4a2 2 0 0 0-1.5 1.5h-3A2 2 0 0 0 9 19.4a2 2 0 0 0-2.2.4l-2.6-2.6A2 2 0 0 0 4.6 15a2 2 0 0 0-1.5-1.5v-3A2 2 0 0 0 4.6 9a2 2 0 0 0-.4-2.2l2.6-2.6A2 2 0 0 0 9 4.6a2 2 0 0 0 1.5-1.5h3A2 2 0 0 0 15 4.6a2 2 0 0 0 2.2-.4l2.6 2.6A2 2 0 0 0 19.4 9a2 2 0 0 0 1.5 1.5v3A2 2 0 0 0 19.4 15z"/>',water:'<path d="M12 2S5 10.1 5 15a7 7 0 0 0 14 0c0-4.9-7-13-7-13Z"/>',pill:'<path d="M10.6 4.4a6 6 0 0 1 8.5 8.5l-6.2 6.2a6 6 0 0 1-8.5-8.5l6.2-6.2ZM8 17l9-9"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',chevronRight:'<path d="m9 18 6-6-6-6"/>',chevronLeft:'<path d="m15 18-6-6 6-6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0l-1 1-1-1a5.5 5.5 0 0 0-7.8 7.8l8.8 8.2 8.8-8.2a5.5 5.5 0 0 0 0-7.8Z"/>',plusCircle:'<circle cx="12" cy="12" r="9"/><path d="M12 8v8M8 12h8"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',upload:'<path d="M12 16V4m-4 4 4-4 4 4M4 17v4h16v-4"/>',trash:'<path d="M4 7h16M10 11v7m4-7v7M6 7l1 14h10l1-14M9 7V4h6v3"/>',flame:'<path d="M12 22a8 8 0 0 0 8-8c0-4-4-7-5-12-2 2-1 5-4 7-1-2-1-4-3-5C8 9 4 11 4 14a8 8 0 0 0 8 8z"/>',note:'<path d="M7 3h10a2 2 0 0 1 2 2v16H5V5a2 2 0 0 1 2-2zm1 5h8M8 12h8M8 16h5"/>',edit:'<path d="m15 5 4 4M4 20l4-.8L19 8a2.8 2.8 0 1 0-4-4L4.8 15 4 20z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',activity:'<path d="M2 12h4l3-7 4 14 3-7h6"/>',coffee:'<path d="M4 7h14v7a7 7 0 0 1-14 0V7zm14 1h2a3 3 0 0 1 0 6h-2M3 21h17"/>',close:'<path d="M18 6 6 18M6 6l12 12"/>'};
Object.assign(ICONS,{cloud:'<path d="M7 18h11a4 4 0 0 0 .5-8A6.5 6.5 0 0 0 6 8.5 4.8 4.8 0 0 0 7 18Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>',refresh:'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>'});
function ic(name,cls=''){return `<svg class="ic ${cls}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.info}</svg>`}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const logoSvg='<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M4 17h6l4-8 5 15 4-8h5" fill="none" stroke="#D6EF91" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const PROGRAMS=[
{id:'mon',short:'SEG',label:'Segunda',name:'Peito + tríceps',color:'#3878d9',desc:'Supinos e exercícios de tríceps com esteira inclinada.',ex:[['Supino reto máquina ou barra',4,'8–10'],['Supino inclinado com halteres',3,'10'],['Crucifixo máquina',3,'12'],['Crossover',3,'12–15'],['Tríceps corda',3,'10–12'],['Tríceps francês',3,'10–12'],['Tríceps barra',2,'12–15'],['Esteira inclinada',1,'15 min','tempo']]},
{id:'tue',short:'TER',label:'Terça',name:'Costas + bíceps',color:'#39a46b',desc:'Remadas, puxadas e bíceps com cardio leve.',ex:[['Puxada frontal',4,'8–10'],['Remada baixa',4,'10'],['Remada unilateral',3,'10 cada lado'],['Pulldown',3,'12'],['Rosca direta',3,'10'],['Rosca alternada',3,'10'],['Rosca martelo',2,'12'],['Esteira ou bike',1,'15 min','tempo']]},
{id:'wed',short:'QUA',label:'Quarta',name:'Pernas',color:'#de735f',desc:'Treino de membros inferiores; adapte cargas e séries na retomada.',ex:[['Agachamento ou Hack',4,'8–10'],['Leg press',4,'10'],['Cadeira extensora',3,'12'],['Mesa flexora',3,'12'],['Stiff',3,'10'],['Cadeira abdutora',3,'15'],['Panturrilha',4,'15'],['Cardio leve',1,'10 min','tempo']]},
{id:'thu',short:'QUI',label:'Quinta',name:'Ombros + braços + abdômen',color:'#e0b559',desc:'Desenvolvimento, braços, abdômen e cardio.',ex:[['Desenvolvimento',4,'8–10'],['Elevação lateral',4,'12'],['Crucifixo inverso',3,'12'],['Rosca Scott',3,'10'],['Rosca martelo',3,'12'],['Tríceps corda',3,'12'],['Tríceps francês',3,'10'],['Abdominal máquina ou cabo',3,'15'],['Prancha',3,'30–45 s','tempo'],['Cardio',1,'15 min','tempo']]},
{id:'fri',short:'SEX',label:'Sexta',name:'Pernas leve + core',color:'#a577cf',desc:'Sessão leve de pernas, abdômen e mobilidade.',ex:[['Cadeira extensora',3,'15'],['Mesa flexora',3,'15'],['Cadeira abdutora',3,'15'],['Panturrilha',3,'15'],['Abdominal',3,'15'],['Prancha',3,'40 s','tempo'],['Mobilidade',1,'5–10 min','tempo']]}];
const MEAL_PLAN=[['Segunda','Arroz, frango desfiado e cenoura cozida'],['Terça','Patinho moído, batata e abobrinha'],['Quarta','Arroz, filé de frango e chuchu'],['Quinta','Arroz, patinho moído e cenoura'],['Sexta','Purê sem leite comum, frango e abobrinha']];
const MEDS=[];
const DEFAULT_SETTINGS={waterGoal:2500,trainingMode:'retorno',medications:[],startedAt:new Date().toISOString().slice(0,10)};
const $=s=>document.querySelector(s);const dayKey=(date)=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;const parseDay=k=>new Date(k+'T12:00:00');const today=()=>dayKey(new Date());const daysShift=(k,n)=>{let d=parseDay(k);d.setDate(d.getDate()+n);return dayKey(d)};
const fmtDate=k=>parseDay(k).toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});const fmtShort=k=>parseDay(k).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});const fmtTime=()=>new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
let page='home',date=today(),programChoice=null,expandedExercise=0,modal=null,toastTimer=null,days={},settings=structuredClone(DEFAULT_SETTINGS),ready=false;
const STORE=window.RitmoStore;
let conflicts=[],guestAvailable=false,authMode='login',authMessage='',editMed=null,authBusy=false,refreshPending=false,localRevision=0;
function freshDay(k){return {date:k,water:0,meals:[],meds:{},workouts:{},weight:'',waist:'',bowel:null,habits:{}}}
function getDay(k=date){return days[k]||freshDay(k)}
function safeDay(k=date){const r=getDay(k);return {...freshDay(k),...r,meds:{...(r.meds||{})},workouts:{...(r.workouts||{})},habits:{...(r.habits||{})},meals:[...(r.meals||[])]}}
async function initStore(){const data=await STORE.init(DEFAULT_SETTINGS);applySnapshot(data);guestAvailable=await STORE.hasGuestData()}
function normalizeSettings(s){const v={...structuredClone(DEFAULT_SETTINGS),...(s||{})};v.medications=Array.isArray(v.medications)?v.medications.filter(m=>m&&typeof m==='object').slice(0,100).map(m=>({id:String(m.id||crypto.randomUUID()).slice(0,100),name:String(m.name||'Medicamento').slice(0,90),dose:String(m.dose||'').slice(0,60),time:/^\d{2}:\d{2}$/.test(m.time)?m.time:'08:00',type:m.type==='supplement'?'supplement':'medicine'})):[];v.waterGoal=clamp(Number(v.waterGoal)||2500,250,6000);v.trainingMode=v.trainingMode==='original'?'original':'retorno';return v} 



async function saveDay(r){localRevision++;const previous=days[r.date];days[r.date]=r;try{await STORE.put('day:'+r.date,r)}catch(err){if(days[r.date]===r){if(previous)days[r.date]=previous;else delete days[r.date]}throw err}}
async function saveSettings(){localRevision++;await STORE.put('settings',settings)}
function notify(msg){const root=$('#toast-root');clearTimeout(toastTimer);root.innerHTML=`<div role="status" class="toast">${esc(msg)}</div>`;toastTimer=setTimeout(()=>root.innerHTML='',3300)}
function medCount(r){return settings.medications.filter(m=>r.meds?.[m.id]).length}
function percent(n,d){return d>0?Math.round(n/d*100):0}
function workoutDone(r){return Object.values(r.workouts||{}).some(w=>w.finishedAt)}
function completion(r){const targets=[Math.min(1,r.water/(settings.waterGoal||2500)),Math.min(1,r.meals.length/3),workoutDone(r)?1:0];if(settings.medications.length)targets.push(medCount(r)/settings.medications.length);return Math.round(targets.reduce((a,b)=>a+b,0)/targets.length*100)}
function header(){return `<header class="app-head"><button class="profile-pill" data-action="account"><span class="profile-orb">${ic('activity')}</span><span><strong>Meu Ritmo</strong><small id="sync-indicator">${esc(syncLabel())}</small></span></button><div class="head-actions"><button class="round-btn" data-action="account" aria-label="Conta e sincronização">${ic('cloud')}</button><button class="round-btn" data-action="page" data-page="settings" aria-label="Abrir ajustes">${ic('settings')}</button></div></header>`}
function dateNav(){return `<div class="date-nav"><button class="date-pill" data-action="go-today">${ic('calendar','sm')} ${date===today()?'Hoje':fmtShort(date)}</button><div class="date-changer"><button aria-label="Dia anterior" class="date-btn" data-action="prev-date">${ic('chevronLeft','sm')}</button><button aria-label="Próximo dia" class="date-btn" data-action="next-date">${ic('chevronRight','sm')}</button></div></div>`}
function section(title,extra=''){return `<div class="section-row"><h2>${title}</h2>${extra}</div>`}
function homePage(){const r=getDay(),p=completion(r),water=clamp(percent(r.water,settings.waterGoal),0,100),prog=chosenProgram();return `${header()}<div class="day-heading"><div><p class="eyebrow">${esc(fmtDate(date))}</p><h1 class="page-title">Sua saúde.<br><span>No seu ritmo.</span></h1></div><button class="calendar-button" data-action="go-today" aria-label="Voltar para hoje">${ic('calendar')}<strong>${Number(date.slice(-2))}</strong></button></div>${dateNav()}<section class="overview-card" aria-label="Resumo do dia"><div class="overview-top"><span>Visão geral</span><span class="pill">${p}% do dia</span></div><div class="rings-row">${ringMetric('water',water,(r.water/1000).toLocaleString('pt-BR',{maximumFractionDigits:1})+' L','Água','home')}${ringMetric('dumbbell',workoutDone(r)?100:0,workoutDone(r)?'Feito':'Pendente','Treino','workout')}${ringMetric('food',Math.min(100,r.meals.length/3*100),String(r.meals.length),'Refeições','food')}${ringMetric('pill',settings.medications.length?medCount(r)/settings.medications.length*100:0,medCount(r)+'/'+settings.medications.length,'Medicamentos','settings')}</div></section><div class="section-row"><h2>Seu cuidado diário</h2><span class="hint">${date===today()?'Hoje':fmtShort(date)}</span></div><div class="dashboard-grid"><section class="water-widget"><div class="widget-label">${ic('water')} Hidratação</div><div class="widget-number">${(r.water/1000).toLocaleString('pt-BR',{maximumFractionDigits:2})}<span> / ${(settings.waterGoal/1000).toLocaleString('pt-BR')} L</span></div><div class="water-bars" aria-label="${water}% da meta">${Array.from({length:20},(_,i)=>`<i class="${i<water/5?'filled':''}"></i>`).join('')}</div><div class="water-actions"><button class="chip-btn muted" data-action="water" data-amount="-200">−200</button><button class="chip-btn" data-action="water" data-amount="200">+200</button><button class="chip-btn primary" data-action="water" data-amount="500">+500 ml</button></div></section><button class="workout-widget" data-action="page" data-page="workout"><div class="widget-label">${ic('dumbbell')} Movimento</div><div class="workout-art" aria-hidden="true">${ic('dumbbell')}</div><strong>${workoutDone(r)?'Treino concluído':esc(prog.name)}</strong><span>${workoutDone(r)?'Boa! Você cuidou de si.':'Abrir treino de hoje'} ${ic('chevronRight','sm')}</span></button></div><div class="quick-row"><button data-action="open-meal">${ic('plus','sm')} Refeição</button><button data-action="page" data-page="progress">${ic('chart','sm')} Medidas</button><button data-action="open-med">${ic('pill','sm')} Medicamento</button></div>${section('Medicamentos',`<button class="subtle-link" data-action="page" data-page="settings">Gerenciar ${ic('chevronRight','sm')}</button>`)}${medCard(r)}${section('Pequenas vitórias','<span class="hint">Um hábito de cada vez</span>')}${habitCard(r)}${!STORE.state.session?`<button class="cloud-invite" data-action="account">${ic('cloud')}<span><strong>Sua rotina, sempre com você</strong><small>Entre para salvar e sincronizar seus registros.</small></span>${ic('chevronRight','sm')}</button>`:''}`}
function ringMetric(icon,value,number,label,target){return `<button class="ring-metric" data-action="page" data-page="${target}"><div class="ring"><svg viewBox="0 0 64 64"><circle class="ring-track" cx="32" cy="32" r="27"/><circle class="ring-fill" cx="32" cy="32" r="27" stroke-dasharray="${clamp(value,0,100)*1.696} 169.65"/></svg><span>${ic(icon)}</span></div><strong>${number}</strong><small>${label}</small></button>`}
function stat(icon,val,label){return `<div class="stat"><div class="stat-ic">${ic(icon,'sm')}</div><div class="stat-number">${esc(val)}</div><div class="stat-label">${esc(label)}</div></div>`}
function waterCard(r){let v=clamp(percent(r.water,settings.waterGoal),0,100);return `<div class="card"><div class="card-head"><h3 class="flex">${ic('water','sm')} Água do dia</h3><span class="pill">Meta ${(settings.waterGoal/1000).toLocaleString('pt-BR',{maximumFractionDigits:2})} L</span></div><div class="water-top"><strong class="water-big">${r.water.toLocaleString('pt-BR')} <span class="water-small">ml</span></strong><span class="water-small">${v}% da meta</span></div><div class="progress"><span style="width:${v}%"></span></div><div class="water-actions"><button class="chip-btn muted" data-action="water" data-amount="-200">−200 ml</button><button class="chip-btn" data-action="water" data-amount="200">+200 ml</button><button class="chip-btn" data-action="water" data-amount="300">+300 ml</button><button class="chip-btn primary" data-action="water" data-amount="500">+500 ml</button></div></div>`}
function medCard(r){return `<div class="card">${settings.medications.length?settings.medications.map(m=>`<div class="med-row"><div class="med-bubble">${ic('pill')}</div><div class="med-info"><strong>${esc(m.name)}</strong><small>${esc(m.dose)} · ${esc(m.time)}</small></div><button class="tiny-check ${r.meds?.[m.id]?'done':''}" data-action="med" data-id="${esc(m.id)}" aria-label="${r.meds?.[m.id]?'Desmarcar':'Marcar'} ${esc(m.name)}">${ic('check')} ${r.meds?.[m.id]?'Tomado':'Marcar'}</button></div>`).join(''):`<div class="empty-state"><span class="empty-icon">${ic('pill')}</span><strong>Seu cuidado, organizado</strong><p>Adicione os medicamentos e horários<br>já orientados pelo seu profissional.</p><button class="btn secondary" data-action="open-med">${ic('plus','sm')} Adicionar medicamento</button></div>`}</div>`}
function mealCard(r){return `<div class="card"><div class="card-head"><h3>Suas refeições</h3><button class="btn ghost" data-action="open-meal">${ic('plus','sm')} Adicionar</button></div>${r.meals.length?r.meals.slice(-4).reverse().map((m)=>`<div class="meal-row"><div class="meal-time">${esc(m.time||'—')}</div><div class="meal-info"><strong>${esc(m.title)}</strong><small>${esc(m.type||'Refeição')} · ${symptomLabel(m.symptom)}</small></div><button class="round-btn" style="width:31px;height:31px;border-radius:9px" data-action="delete-meal" data-id="${esc(m.id)}" aria-label="Excluir refeição">${ic('trash','sm')}</button></div>`).join(''):`<div class="empty-note">Você ainda não registrou refeições neste dia. Comece pelo almoço ou café da manhã.</div>`}</div>`}
const HABITS=[['sem-energetico','Sem energético'],['sem-alcool','Sem álcool'],['sem-refrigerante','Sem refrigerante'],['sem-palheiro','Sem palheiro']];
function habitCard(r){return `<div class="habit-list">${HABITS.map(([id,label])=>`<button class="habit ${r.habits?.[id]?'yes':''}" data-action="habit" data-id="${id}"><span>${esc(label)}</span>${ic(r.habits?.[id]?'check':'plus','sm')}</button>`).join('')}</div><div class="small-note mt8">Marque somente quando tiver cumprido o hábito. Não marcar não significa que você consumiu.</div>`}
function chosenProgram(){return PROGRAMS.find(p=>p.id===programChoice)||PROGRAMS[clamp(parseDay(date).getDay()-1,0,4)]}
function isDuration(e){return e[3]==='tempo'}
function setCount(ex){return isDuration(ex)?1:settings.trainingMode==='retorno'?Math.min(2,ex[1]):ex[1]}
function workoutPage(){const r=getDay(),p=chosenProgram(),sess=r.workouts?.[p.id],settotal=p.ex.reduce((sum,e)=>sum+setCount(e),0),setdone=p.ex.reduce((sum,e,i)=>sum+(sess?.sets?.[i]||[]).filter(x=>x.done).length,0);return `${header()}<div class="eyebrow">SEU PROGRAMA</div><h1 class="page-title">Treinos</h1><p class="subtitle">Seu programa, suas séries e suas cargas em um só lugar.</p>${dateNav()}<div class="day-tabs">${PROGRAMS.map(d=>`<button class="day-tab ${d.id===p.id?'active':''}" data-action="program" data-program="${d.id}">${d.short}<b>${esc(d.label.slice(0,3))}</b></button>`).join('')}</div><div class="work-hero"><div class="work-label" style="color:${p.color}">${p.label.toUpperCase()} · ${settings.trainingMode==='retorno'?'MODO RETOMADA':'PLANO ORIGINAL'}</div><div class="work-title">${esc(p.name)}</div><div class="work-desc">${esc(p.desc)}</div><div class="flex mt16"><span class="pill dark">${p.ex.length} exercícios</span><span class="pill">${settings.trainingMode==='retorno'?'2 séries por exercício de força':'Séries do plano'}</span></div></div><div class="card mt12"><div class="card-head"><h3>Sessão selecionada</h3><span class="pill ${sess?.finishedAt?'':'warn'}">${sess?.finishedAt?'Concluída':sess?'Em andamento':'Não iniciada'}</span></div><p class="subtitle m0 mt8">${sess?'Séries marcadas: '+setdone+' de '+settotal+'. Registre as cargas que realmente utilizou.':'Inicie a sessão para registrar séries, repetições e cargas.'}</p>${sess?`<div class="progress mt12"><span style="width:${percent(setdone,settotal)}%"></span></div><button class="btn ${sess.finishedAt?'secondary':''} full mt12" data-action="finish-workout" data-program="${p.id}">${ic('check','sm')} ${sess.finishedAt?'Reabrir sessão':'Concluir treino'}</button>`:`<button class="btn full mt12" data-action="start-workout" data-program="${p.id}">${ic('plusCircle','sm')} Iniciar treino</button>`}</div>${section('Exercícios',`<span class="hint">${setdone}/${settotal} séries</span>`)}<div class="ex-list">${p.ex.map((e,i)=>exerciseCard(e,i,sess,p.id)).join('')}</div><div class="info-box mt20">${ic('info','sm')} O modo retomada mostra menos séries. Use o programa e as cargas definidos com o profissional que acompanha seus treinos.</div><div class="action-row mt12"><button class="btn secondary full" data-action="page" data-page="settings">${ic('settings','sm')} Ajustar modo de treino</button></div>`}
function exerciseCard(ex,i,sess,pid){const n=setCount(ex),arr=sess?.sets?.[i]||[],done=arr.filter(x=>x.done).length,open=expandedExercise===i;return `<div class="ex-card"><button style="border:0;background:none;width:100%;text-align:left" class="ex-top" data-action="expand-exercise" data-index="${i}"><span class="ex-num">${String(i+1).padStart(2,'0')}</span><span class="ex-detail"><strong>${esc(ex[0])}</strong><small>${n} ${n===1?'série':'séries'} · ${esc(ex[2])}${sess?' · '+done+'/'+n+' registradas':''}</small></span><span class="ex-exp">${ic('chevronRight','sm')}</span></button>${open?`<div class="set-board">${sess?`<div class="set-head"><span>Série</span><span>${isDuration(ex)?'Tempo':'Reps'}</span><span>Carga kg</span><span>Feita</span></div>${Array.from({length:n},(_,j)=>{const s=arr[j]||{};return `<div class="set-row"><b>${j+1}ª</b><input aria-label="Repetições ou tempo da série ${j+1}" data-field="set-reps" data-program="${pid}" data-ex="${i}" data-set="${j}" value="${esc(s.reps??ex[2])}"><input aria-label="Carga da série ${j+1}" type="text" inputmode="decimal" data-field="set-kg" data-program="${pid}" data-ex="${i}" data-set="${j}" placeholder="—" value="${esc(s.kg??'')}"><button class="square-check ${s.done?'checked':''}" aria-label="Marcar série ${j+1} ${s.done?'como não feita':'como feita'}" data-action="set-done" data-program="${pid}" data-ex="${i}" data-set="${j}">${s.done?ic('check','sm'):''}</button></div>`}).join('')}`:`<div class="small-note">Inicie o treino acima para registrar suas séries e cargas.</div>`}<div class="set-helper">${isDuration(ex)?'Atividade por tempo: registre a duração no campo correspondente.':'Use cargas confortáveis e peça ao instrutor para conferir a técnica.'}</div></div>`:''}</div>`}
function foodPage(){const r=getDay();return `${header()}<div class="eyebrow">COMER BEM SEM PASSAR MAL</div><h1 class="page-title">Alimentação</h1><p class="subtitle">Marmitas simples, registro das refeições e diário digestivo.</p>${dateNav()}<div class="info-box green">${ic('check','sm')} Registre suas refeições e como você se sentiu para acompanhar sua rotina ao longo dos dias.</div>${section('Registro do dia',`<button class="subtle-link" data-action="open-meal">+ Nova refeição</button>`)}${mealCard(r)}${section('Sintomas intestinais','<span class="hint">Registre sem julgamento</span>')}<div class="card"><div class="card-head"><h3>Como esteve seu intestino?</h3><button class="subtle-link" data-action="open-bowel">Editar</button></div><p class="subtitle m0 mt8">${r.bowel?`<strong style="color:var(--ink)">${esc(r.bowel.status)}</strong> · ${esc(r.bowel.description||'Sem detalhes')}`:'Sem registro neste dia.'}</p></div>${section('Marmitas da semana','<span class="hint">Referências iniciais</span>')}<div class="card">${MEAL_PLAN.map((m,i)=>`<div class="meal-suggestion"><div class="meal-day-icon">${ic('food','sm')}</div><div><strong>${m[0]}</strong><p>${m[1]}</p></div></div>`).join('')}</div><div class="info-box mt16">Estas ideias são apenas referências de organização. Siga o plano alimentar definido com o profissional que acompanha você.</div>`}
function weightChart(){const vals=Object.values(days).filter(x=>x&&typeof x.date==='string'&&x.weight!==undefined&&x.weight!==''&&Number.isFinite(Number(String(x.weight).replace(',','.')))).map(x=>({d:x.date,v:Number(String(x.weight).replace(',','.'))})).filter(x=>x.v>=30&&x.v<=300).sort((a,b)=>a.d.localeCompare(b.d));if(vals.length<2)return `<div class="empty-note">Registre seu peso em pelo menos dois dias para visualizar a tendência.</div>`;const a=vals.slice(-15),min=Math.min(...a.map(x=>x.v))-1,max=Math.max(...a.map(x=>x.v))+1,span=max-min||1;const pts=a.map((x,i)=>({x:20+i/(a.length-1)*290,y:118-((x.v-min)/span)*92,v:x.v,d:x.d}));const path=pts.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ');return `<svg viewBox="0 0 330 145" role="img" aria-label="Histórico de peso, de ${a[0].v} a ${a[a.length-1].v} quilos" style="width:100%;height:145px"><path d="M20 118H310" stroke="#e9eee9" stroke-width="2"/><path d="${path}" fill="none" stroke="#2b7359" stroke-linecap="round" stroke-linejoin="round" stroke-width="3"/>${pts.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="3.3" fill="#2b7359"/>`).join('')}<text x="20" y="139" fill="#8c9a91" font-size="10">${a[0].v.toLocaleString('pt-BR')} kg</text><text x="310" y="139" text-anchor="end" fill="#397359" font-size="10">${a[a.length-1].v.toLocaleString('pt-BR')} kg</text></svg>`}
function progressPage(){const r=getDay(),end=date,range=Array.from({length:7},(_,i)=>daysShift(end,i-6)),waterReached=range.filter(d=>getDay(d).water>=settings.waterGoal).length,trained=range.filter(d=>workoutDone(getDay(d))).length,medAdhered=range.filter(d=>{const rr=getDay(d);return settings.medications.length>0&&medCount(rr)===settings.medications.length}).length;const todayStr=today();const last28=Array.from({length:28},(_,i)=>daysShift(todayStr,i-27));return `${header()}<div class="eyebrow">SUA JORNADA</div><h1 class="page-title">Evolução</h1><p class="subtitle">Acompanhe hábitos, medidas e consistência — sem se prender só à balança.</p>${dateNav()}<div class="stat-grid">${stat('dumbbell',trained,'Treinos · últimos 7 dias')}${stat('water',waterReached+'/7','Meta de água atingida')}${stat('pill',medAdhered+'/7','Dias com registros completos')}${stat('activity',Object.values(days).filter(x=>workoutDone(x)).length,'Treinos acumulados')}</div>${section('Seu peso e cintura','<span class="hint">Atualize quando medir</span>')}<div class="card"><div class="form-grid"><div><label class="form-label" for="weight">Peso (kg)</label><input class="field" id="weight" inputmode="decimal" placeholder="Ex.: 87,0" value="${esc(r.weight)}" data-field="weight"></div><div><label class="form-label" for="waist">Cintura (cm)</label><input class="field" id="waist" inputmode="decimal" placeholder="Ex.: 100" value="${esc(r.waist)}" data-field="waist"></div></div><div class="small-note mt12">Os valores são salvos quando você sai do campo. Meça a cintura no mesmo ponto e horário, de preferência uma vez por semana.</div></div>${section('Histórico de peso','<span class="hint">Últimas medições</span>')}<div class="card">${weightChart()}</div>${section('Água nos últimos 7 dias','<span class="hint">ml por dia</span>')}<div class="card"><div class="chart">${range.map(k=>{const rr=getDay(k),height=clamp(Math.round((rr.water/(settings.waterGoal||2500))*91),3,95);return `<div class="chart-col"><div class="chartbar ${rr.water?'':'low'}" style="height:${height}%" title="${k}: ${rr.water} ml"></div><small>${parseDay(k).toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}</small></div>`}).join('')}</div><p class="small-note m0 mt16">Meta diária atual: ${settings.waterGoal.toLocaleString('pt-BR')} ml. Ajuste conforme orientação e condições de saúde.</p></div>${section('Calendário de treinos','<span class="hint">Últimos 28 dias</span>')}<div class="card"><div class="calendar">${last28.map(k=>`<button class="cal-cell ${workoutDone(getDay(k))?'trained':''} ${k===todayStr?'today':''}" data-action="select-day" data-day="${k}" title="${k}">${Number(k.slice(-2))}</button>`).join('')}</div><div class="small-note mt12"><span style="color:var(--brand)">■</span> Dia com treino concluído · toque para ver o registro.</div></div>${section('Hábitos no período','<span class="hint">Últimos 7 dias</span>')}<div class="card">${HABITS.map(([id,label])=>{const count=range.filter(k=>getDay(k).habits?.[id]).length;return `<div class="setting-row"><div><strong>${label}</strong><small>${count} dos últimos 7 dias marcados</small></div><span class="pill">${count}/7</span></div>`}).join('')}</div>`}
function settingsPage(){const signed=STORE.state.session;return `${header()}<div class="eyebrow">DO SEU JEITO</div><h1 class="page-title">Ajustes</h1><p class="subtitle">Uma rotina que combina com você.</p><button class="account-card" data-action="account"><span class="profile-orb">${ic('user')}</span><span><strong>${signed?'Sua conta':'Entrar no Ritmo'}</strong><small>${signed?esc(signed.user.email||'Conta conectada'):'Salve seus registros na nuvem'}</small></span>${ic('chevronRight')}</button>${section('Metas e treinamento')}<div class="card settings-group"><div class="setting-row"><div><strong>Meta de água</strong><small>Mililitros por dia</small></div><input aria-label="Meta diária de água em mililitros" class="field" inputmode="numeric" type="number" min="250" max="6000" step="50" value="${settings.waterGoal}" data-field="goal"></div><div class="setting-row"><div><strong>Modo de treino</strong><small>Séries ajustadas para sua retomada</small></div><select class="field" aria-label="Modo de treino" data-field="trainingMode"><option value="retorno" ${settings.trainingMode==='retorno'?'selected':''}>Retomada</option><option value="original" ${settings.trainingMode==='original'?'selected':''}>Original</option></select></div></div>${section('Medicamentos e suplementos')}<div class="card settings-group">${settings.medications.map(m=>`<div class="setting-row"><button class="med-edit" data-action="edit-med" data-id="${esc(m.id)}"><strong>${esc(m.name)}</strong><small>${esc(m.dose)} · ${esc(m.time)}</small></button><button class="round-btn" aria-label="Editar ${esc(m.name)}" data-action="edit-med" data-id="${esc(m.id)}">${ic('edit','sm')}</button><button class="round-btn danger-icon" aria-label="Remover ${esc(m.name)}" data-action="delete-med" data-id="${esc(m.id)}">${ic('trash','sm')}</button></div>`).join('')}<button class="settings-link" data-action="open-med">${ic('plus')} Adicionar ao controle</button></div><p class="small-note">Registre somente o que já foi prescrito ou orientado. O Ritmo não indica doses e não envia alarmes com o app fechado.</p>${section('Seus dados')}<div class="card settings-group">${settingsAction('export','download','Exportar backup','Uma cópia dos seus registros')}${settingsAction('import','upload','Importar backup','Restaurar ou trazer dados do aparelho')}${settingsAction('account','cloud','Conta e sincronização',syncLabel())}${settingsAction('reset','trash','Apagar registros','Remove os registros desta conta',true)}</div><p class="small-note">Com a conta conectada, seus registros são salvos no Supabase e ficam disponíveis ao entrar em outro aparelho. Sem internet, as alterações ficam neste dispositivo até sincronizar.</p>${section('No seu iPhone')}<div class="card settings-group">${settingsAction('install-help','plusCircle','Adicionar à Tela de Início','Abrir o Ritmo como aplicativo')}</div><p class="version-note">Ritmo 2.0 <span>•</span> Um dia de cada vez.</p>`}
function settingsAction(action,icon,title,sub,danger=false){return `<button class="settings-link ${danger?'danger-text':''}" data-action="${action}"><span class="settings-icon">${ic(icon)}</span><span><strong>${title}</strong><small>${esc(sub)}</small></span>${ic('chevronRight','sm')}</button>`}
function symptomLabel(s){return ({nenhum:'Sem sintomas',leve:'Leve desconforto',diarreia:'Diarreia',forte:'Desconforto forte'})[s]||'Sem avaliação'}
function modalHtml(){if(!modal)return '';const close=`<button class="sheet-close" data-action="close-modal" aria-label="Fechar">${ic('close','sm')}</button>`;let title='',body='';
if(modal==='auth'){title=STORE.state.session?'Sua conta':authMode==='signup'?'Criar sua conta':authMode==='reset'?'Recuperar acesso':authMode==='new-password'?'Nova senha':'Entre no seu ritmo';body=accountBody()}
else if(modal==='med'){title=editMed?'Editar medicamento':'Adicionar ao controle';body=`<p class="subtitle">Organize o que já foi orientado pelo seu profissional de saúde.</p><div class="field-wrap"><label class="form-label" for="med-name">Nome</label><input class="field" id="med-name" maxlength="90" value="${esc(editMed?.name||'')}" placeholder="Nome do medicamento ou suplemento"></div><div class="field-wrap"><label class="form-label" for="med-dose">Dose prescrita</label><input class="field" id="med-dose" maxlength="60" value="${esc(editMed?.dose||'')}" placeholder="Como consta na sua orientação"></div><div class="form-grid"><div class="field-wrap"><label class="form-label" for="med-time">Horário</label><input class="field" type="time" id="med-time" value="${esc(editMed?.time||'08:00')}"></div><div class="field-wrap"><label class="form-label" for="med-type">Tipo</label><select class="field" id="med-type"><option value="medicine">Medicamento</option><option value="supplement" ${editMed?.type==='supplement'?'selected':''}>Suplemento</option></select></div></div><label class="consent"><input id="med-confirm" type="checkbox" ${editMed?'checked':''}> Estou seguindo a orientação do meu profissional de saúde.</label><button class="btn full" data-action="save-med">Salvar</button>`}
else if(modal==='meal'){title='Registrar refeição';body=`<div class="field-wrap"><label class="form-label" for="meal-title">O que você comeu?</label><input id="meal-title" class="field" placeholder="Ex.: arroz, frango e cenoura" maxlength="200"></div><div class="form-grid"><div class="field-wrap"><label class="form-label" for="meal-type">Refeição</label><select id="meal-type" class="field"><option>Café da manhã</option><option>Almoço</option><option>Lanche</option><option>Jantar</option><option>Ceia</option></select></div><div class="field-wrap"><label class="form-label" for="meal-time">Horário</label><input type="time" id="meal-time" class="field" value="${fmtTime()}"></div></div><div class="field-wrap"><label class="form-label">Como se sentiu depois?</label><select id="meal-symptom" class="field"><option value="nenhum">Sem sintomas</option><option value="leve">Desconforto leve</option><option value="diarreia">Diarreia</option><option value="forte">Desconforto forte</option></select></div><div class="field-wrap"><label class="form-label" for="meal-notes">Observações (opcional)</label><textarea class="field" id="meal-notes" rows="2" placeholder="Molho, lactose, tempo até o desconforto..."></textarea></div><button class="btn full" data-action="save-meal">${ic('check','sm')} Salvar refeição</button>`}
else if(modal==='bowel'){const b=getDay().bowel;title='Registro intestinal';body=`<div class="field-wrap"><label class="form-label">Como esteve seu intestino?</label><select class="field" id="bowel-status">${['Normal','Gases ou estufamento','Fezes amolecidas','Diarreia','Constipação','Não evacuei'].map(s=>`<option ${b?.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field-wrap"><label class="form-label">Observações</label><textarea id="bowel-notes" class="field" rows="3" placeholder="Quando começou, quantas vezes, que alimentos comeu...">${esc(b?.description||'')}</textarea></div><button class="btn full" data-action="save-bowel">${ic('check','sm')} Salvar registro</button>`}
else if(modal==='supp'){title='Suplemento autorizado';body=`<div class="info-box mb12">Adicione apenas suplementos ou vitaminas que já tenham sido orientados ou validados por seu profissional de saúde. Não iniciamos nenhuma vitamina automaticamente.</div><div class="field-wrap"><label class="form-label">Nome do suplemento</label><input class="field" id="supp-name" maxlength="90" placeholder="Ex.: vitamina prescrita"></div><div class="form-grid"><div class="field-wrap"><label class="form-label">Dose</label><input class="field" id="supp-dose" maxlength="30" placeholder="Ex.: 1 cápsula"></div><div class="field-wrap"><label class="form-label">Horário</label><input class="field" id="supp-time" type="time" value="12:00"></div></div><label class="flex tiny-text mb12"><input id="supp-confirm" type="checkbox"> Foi orientado ou validado por profissional de saúde</label><button class="btn full" data-action="save-supp">${ic('check','sm')} Adicionar ao controle</button>`}
else if(modal==='install'){title='Instalar no iPhone';body=`<p class="subtitle">Tenha o Ritmo sempre à mão, com um ícone na sua Tela de Início.</p><div class="card"><div class="meal-suggestion"><div class="ex-num">1</div><div><strong>Abra o endereço no Safari</strong><p>Não basta abrir o arquivo HTML pelo aplicativo Arquivos.</p></div></div><div class="meal-suggestion"><div class="ex-num">2</div><div><strong>Toque em Compartilhar</strong><p>Escolha a opção “Adicionar à Tela de Início”.</p></div></div><div class="meal-suggestion"><div class="ex-num">3</div><div><strong>Selecione “Abrir como App”</strong><p>Se a opção aparecer, ative e toque em Adicionar.</p></div></div></div><div class="info-box mt12">Entre na sua conta pelo app instalado para sincronizar os registros. Depois do primeiro carregamento, você também pode usar o Ritmo offline.</div>`}
return `<div class="modal-backdrop" data-action="close-backdrop"><div class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-bar"></div><div class="sheet-head"><h3>${esc(title)}</h3>${close}</div>${body}</div></div>`}
function render(){if(!ready)return;const pages={home:homePage,workout:workoutPage,food:foodPage,progress:progressPage,settings:settingsPage};$('#view').innerHTML=pages[page]();const tabs=[['home','Hoje','home'],['workout','Treinos','dumbbell'],['food','Refeições','food'],['progress','Evolução','chart'],['settings','Ajustes','settings']];$('#nav').innerHTML=tabs.map(([id,label,icon])=>`<button class="nav-btn ${page===id?'active':''}" data-action="page" data-page="${id}" aria-current="${page===id?'page':'false'}">${ic(icon)}<span>${label}</span></button>`).join('');$('#modal-root').innerHTML=modalHtml()}
function scrollTop(){window.scrollTo({top:0,behavior:'instant'})}
function workingSession(pid){let r=safeDay();let w=r.workouts[pid];if(!w)w={startedAt:new Date().toISOString(),finishedAt:null,sets:{}};w.sets=w.sets||{};return {r,w}}
async function act(name,el){let r=safeDay();const id=el.dataset.id,pid=el.dataset.program;
switch(name){
case 'account':guestAvailable=await STORE.hasGuestData();conflicts=(await STORE.snapshot()).conflicts;authMessage='';modal='auth';authMode='login';break;
case 'auth-mode':authMode=el.dataset.mode;authMessage='';modal='auth';break;
case 'sync':await STORE.sync();await refreshData();notify(syncLabel());break;
case 'signout':if((await STORE.snapshot()).pending&&!confirm('Há alterações pendentes neste aparelho. Elas serão enviadas quando você entrar novamente nesta mesma conta. Deseja sair?'))return;await STORE.signOut();await refreshData();modal=null;break;
case 'import-local':if(!confirm('Enviar os registros locais deste aparelho para a conta conectada?'))return;await STORE.importGuest();await refreshData();guestAvailable=false;notify('Registros preparados para sincronizar.');break;
case 'resolve-conflict':await STORE.resolveConflict(el.dataset.key,el.dataset.choice==='local');await refreshData();break;
case 'open-med':editMed=null;modal='med';break;
case 'edit-med':editMed=settings.medications.find(m=>m.id===id);modal='med';break;
case 'delete-med':if(confirm('Remover este item do seu controle?')){settings.medications=settings.medications.filter(m=>m.id!==id);await saveSettings()}break;
case 'save-med':{const name=$('#med-name').value.trim(),dose=$('#med-dose').value.trim(),time=$('#med-time').value,type=$('#med-type').value;if(!name||!dose||!time){notify('Preencha nome, dose e horário.');return}if(!$('#med-confirm').checked){notify('Confirme que segue a orientação profissional.');return}const med={id:editMed?.id||'med-'+crypto.randomUUID(),name,dose,time,type};if(editMed)settings.medications=settings.medications.map(m=>m.id===editMed.id?med:m);else settings.medications.push(med);await saveSettings();modal=null;notify('Controle atualizado.');break}
case 'page':page=el.dataset.page;modal=null;if(page==='workout')programChoice=null;scrollTop();break;
case 'prev-date':date=daysShift(date,-1);programChoice=null;scrollTop();break;case 'next-date':date=daysShift(date,1);programChoice=null;scrollTop();break;case 'go-today':date=today();programChoice=null;scrollTop();break;case 'select-day':date=el.dataset.day;page='home';scrollTop();break;
case 'water':r.water=Math.max(0,r.water+Number(el.dataset.amount));await saveDay(r);break;
case 'med':r.meds[id]?delete r.meds[id]:r.meds[id]={takenAt:new Date().toISOString()};await saveDay(r);break;
case 'habit':r.habits[id]=!r.habits[id];await saveDay(r);break;
case 'open-meal':modal='meal';break;case 'open-bowel':modal='bowel';break;case 'open-supp':modal='supp';break;case 'install-help':modal='install';break;
case 'close-modal':modal=null;break;
case 'close-backdrop':if(el===el.ownerDocument.querySelector('.modal-backdrop'))modal=null;break;
case 'save-meal':{const title=$('#meal-title')?.value.trim();if(!title){notify('Escreva o que você comeu.');return}r.meals.push({id:'meal-'+Date.now(),title,type:$('#meal-type').value,time:$('#meal-time').value,symptom:$('#meal-symptom').value,notes:$('#meal-notes').value.trim()});await saveDay(r);modal=null;notify('Refeição registrada.');break}
case 'delete-meal':if(confirm('Excluir esta refeição?')){r.meals=r.meals.filter(m=>m.id!==id);await saveDay(r)}break;
case 'save-bowel':r.bowel={status:$('#bowel-status').value,description:$('#bowel-notes').value.trim(),loggedAt:new Date().toISOString()};await saveDay(r);modal=null;notify('Sintomas registrados.');break;
case 'program':programChoice=el.dataset.program;expandedExercise=0;break;
case 'expand-exercise':expandedExercise=expandedExercise===Number(el.dataset.index)?-1:Number(el.dataset.index);break;
case 'start-workout':{const {r:rr,w}=workingSession(pid);rr.workouts[pid]=w;await saveDay(rr);expandedExercise=0;notify('Treino iniciado.');break}
case 'finish-workout':{const {r:rr,w}=workingSession(pid);w.finishedAt=w.finishedAt?null:new Date().toISOString();rr.workouts[pid]=w;await saveDay(rr);notify(w.finishedAt?'Treino concluído!':'Treino reaberto.');break}
case 'set-done':{const {r:rr,w}=workingSession(pid);const ex=Number(el.dataset.ex),s=Number(el.dataset.set),p=PROGRAMS.find(x=>x.id===pid);if(!p)return;const a=w.sets[ex]||[];a[s]=a[s]||{reps:p.ex[ex][2],kg:'',done:false};a[s].done=!a[s].done;w.sets[ex]=a;rr.workouts[pid]=w;await saveDay(rr);break}
case 'save-supp':{const name=$('#supp-name')?.value.trim(),dose=$('#supp-dose')?.value.trim(),time=$('#supp-time')?.value;if(!name||!dose||!time){notify('Preencha todos os campos.');return}if(!$('#supp-confirm').checked){notify('Confirme a orientação profissional.');return}settings.medications.push({id:'supp-'+Date.now(),name,dose,time,type:'supplement'});await saveSettings();modal=null;notify('Suplemento adicionado.');break}
case 'delete-supp':if(confirm('Remover este suplemento do seu controle?')){settings.medications=settings.medications.filter(x=>x.id!==id);await saveSettings();notify('Suplemento removido.')}break;
case 'export':await exportBackup();break;case 'import':$('#import-file').click();return;case 'reset':await resetData();break;
}if(refreshPending&&!modal){await refreshData();refreshPending=false}render()}
async function onChange(el){let field=el.dataset.field;if(!field)return;let r=safeDay();if(field==='weight'||field==='waist'){r[field]=el.value.replace(',','.').slice(0,20);await saveDay(r);notify('Medida salva.');return}if(field==='goal'){settings.waterGoal=clamp(Number(el.value)||2500,250,6000);await saveSettings();render();return}if(field==='trainingMode'){settings.trainingMode=el.value==='original'?'original':'retorno';await saveSettings();render();return}if(field==='med-time'){const m=settings.medications.find(m=>m.id===el.dataset.id);if(m){m.time=el.value||m.time;await saveSettings();notify('Horário atualizado.');}return}if(field==='set-kg'||field==='set-reps'){const pid=el.dataset.program,ex=Number(el.dataset.ex),s=Number(el.dataset.set),p=PROGRAMS.find(x=>x.id===pid);if(!p)return;const {r:rr,w}=workingSession(pid);const a=w.sets[ex]||[];a[s]=a[s]||{reps:p.ex[ex][2],kg:'',done:false};if(field==='set-kg')a[s].kg=el.value.slice(0,20);else a[s].reps=el.value.slice(0,30);w.sets[ex]=a;rr.workouts[pid]=w;await saveDay(rr);return}}
async function exportBackup(){const content={app:'ritmo-pwa',version:2,exportedAt:new Date().toISOString(),settings,days};const blob=new Blob([JSON.stringify(content,null,2)],{type:'application/json'});const file=new File([blob],`ritmo-backup-${today()}.json`,{type:'application/json'});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Backup Ritmo'});notify('Backup enviado para compartilhamento.');return}}catch(e){if(e.name==='AbortError')return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);notify('Backup gerado. Salve no app Arquivos.');}
async function resetData(){if(!confirm('Apagar seus registros? Se a conta estiver conectada, a exclusão também será sincronizada. Exporte um backup antes.'))return;await STORE.importAll({days:{},settings:structuredClone(DEFAULT_SETTINGS)});await refreshData();date=today();page='home';notify('Registros apagados.')}
$('#import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw Error('Use um backup de até 10 MB.');const data=JSON.parse(await file.text());if(data.app!=='ritmo-pwa'||![1,2].includes(data.version)||!data.days||Array.isArray(data.days)||typeof data.days!=='object'||!data.settings)throw Error('Este arquivo não é um backup do Ritmo.');const clean={days:{},settings:normalizeSettings(data.settings)};for(const row of Object.values(data.days)){if(row&&/^\d{4}-\d{2}-\d{2}$/.test(row.date||''))clean.days[row.date]=normalizeDay(row)}if(!confirm('Importar este backup e substituir os registros desta conta? As alterações serão sincronizadas se você estiver conectado.'))return;await STORE.importAll(clean);await refreshData();date=today();page='home';render();notify('Backup importado.')}catch(err){notify(err.message||'Não foi possível importar esse arquivo.')}});
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el)return;if(el.classList.contains('modal-backdrop')&&ev.target!==el)return;ev.preventDefault();try{await act(el.dataset.action,el)}catch(err){notify(err.message||'Não foi possível salvar. Tente novamente.')}});
document.addEventListener('change',async ev=>{if(ev.target.dataset.field)try{await onChange(ev.target)}catch(err){notify('Não foi possível salvar. Faça um backup para proteger seus registros.')}});

function syncLabel(){const s=STORE.state;return ({local:'Salvo neste iPhone',pending:'Aguardando sincronização',syncing:'Sincronizando…',offline:'Offline · salvo no aparelho',synced:'Tudo sincronizado',conflict:'Revisar alterações',error:'Sincronização pendente'})[s.status]||'Salvo no aparelho'}
function normalizeDay(r){const d={...freshDay(r.date),...r};d.water=clamp(Number(d.water)||0,0,30000);d.meals=Array.isArray(d.meals)?d.meals.filter(x=>x&&typeof x==='object').slice(0,200).map(x=>({id:String(x.id||crypto.randomUUID()),title:String(x.title||'').slice(0,200),type:String(x.type||'').slice(0,60),time:String(x.time||'').slice(0,10),symptom:String(x.symptom||'nenhum'),notes:String(x.notes||'').slice(0,2000)})):[];for(const k of ['meds','workouts','habits'])if(!d[k]||typeof d[k]!=='object'||Array.isArray(d[k]))d[k]={};d.weight=String(d.weight||'').slice(0,20);d.waist=String(d.waist||'').slice(0,20);return d}
function applySnapshot(data){days=Object.fromEntries(Object.entries(data.days).map(([k,r])=>[k,normalizeDay(r)]));settings=normalizeSettings(data.settings);conflicts=data.conflicts||[]}
async function refreshData(){const revision=localRevision,owner=STORE.state.owner;const data=await STORE.snapshot();if(owner!==STORE.state.owner)return;if(revision!==localRevision){refreshPending=true;return}applySnapshot(data);guestAvailable=await STORE.hasGuestData()}
function accountBody(){const state=STORE.state;if(state.session&&authMode!=='new-password')return `<div class="account-summary"><span class="profile-orb">${ic('user')}</span><strong>${esc(state.session.user.email||'Conta conectada')}</strong><span class="sync-caption">${esc(syncLabel())}</span></div>${state.error?`<p class="form-message error">${esc(state.error)}</p>`:''}<button class="btn full" data-action="sync">${ic('refresh','sm')} Sincronizar agora</button>${guestAvailable?`<div class="migration-card"><strong>Você já tem registros neste aparelho</strong><p>Traga esses dados para sua conta e continue de onde parou.</p><button class="btn secondary full" data-action="import-local">Trazer registros do aparelho</button></div>`:''}${conflicts.map(c=>`<div class="migration-card"><strong>Alterações em dois aparelhos</strong><p>${c.key==='settings'?'Seus ajustes':`Registros de ${esc(fmtShort(c.key.slice(4)))}`} mudaram enquanto você estava offline. Escolha a versão que deseja manter.</p><div class="action-row"><button class="btn secondary" data-action="resolve-conflict" data-key="${esc(c.key)}" data-choice="remote">Usar a nuvem</button><button class="btn" data-action="resolve-conflict" data-key="${esc(c.key)}" data-choice="local">Usar este aparelho</button></div></div>`).join('')}<p class="small-note mt16">Seus registros ficam privados na sua conta. Alterações feitas sem internet são enviadas quando a conexão volta.</p><button class="text-button danger-text full" data-action="signout">Sair da conta</button>`;const reset=authMode==='reset',recover=authMode==='new-password',signup=authMode==='signup';return `<p class="subtitle">${reset?'Enviaremos um link para você recuperar o acesso.':recover?'Escolha uma senha de pelo menos 8 caracteres.':'Seus cuidados, guardados com você. Entre para acessar sua rotina em outros aparelhos.'}</p><form id="auth-form">${!recover?`<div class="field-wrap"><label class="form-label" for="auth-email">E-mail</label><input class="field" id="auth-email" name="email" type="email" autocomplete="email" inputmode="email" required placeholder="voce@exemplo.com"></div>`:''}${!reset?`<div class="field-wrap"><label class="form-label" for="auth-password">${recover?'Nova senha':'Senha'}</label><input class="field" id="auth-password" name="password" type="password" autocomplete="${signup||recover?'new-password':'current-password'}" minlength="${signup||recover?8:1}" maxlength="128" required placeholder="${signup||recover?'Pelo menos 8 caracteres':'Sua senha'}"></div>`:''}<div id="auth-message" class="form-message" role="status">${esc(authMessage)}</div><button class="btn full" type="submit">${reset?'Enviar link':signup?'Criar conta':recover?'Salvar nova senha':'Entrar'}</button></form>${!recover?`<div class="auth-options"><button class="text-button" data-action="auth-mode" data-mode="${signup||reset?'login':'signup'}">${signup||reset?'Já tenho uma conta':'Criar minha conta'}</button>${!reset&&!signup?'<button class="text-button muted-text" data-action="auth-mode" data-mode="reset">Esqueci minha senha</button>':''}</div>`:''}<p class="privacy-caption">${ic('lock','sm')} Seus registros são acessíveis somente pela sua conta.</p>`}
document.addEventListener('submit',async ev=>{if(ev.target.id!=='auth-form')return;ev.preventDefault();if(authBusy)return;const email=$('#auth-email')?.value.trim(),password=$('#auth-password')?.value;const button=ev.target.querySelector('button[type="submit"]');authBusy=true;button.disabled=true;button.textContent='Aguarde…';try{const result=await STORE.auth(authMode,email,password);if(authMode==='signup'&&!result?.session){authMessage='Conta criada. Confira seu e-mail e confirme o cadastro. Depois entre no Ritmo.';authMode='login';render()}else if(authMode==='reset'){authMessage='Se este e-mail tiver uma conta, você receberá um link de recuperação.';render()}else if(authMode==='new-password'){modal=null;authMode='login';notify('Senha atualizada.');render()}else{modal=null;await refreshData();render();notify('Conta conectada.')}}catch(err){const message=$('#auth-message');if(message){message.textContent=err.message;message.classList.add('error')}}finally{authBusy=false;if(button.isConnected){button.disabled=false;button.textContent=authMode==='signup'?'Criar conta':authMode==='reset'?'Enviar link':'Entrar'}}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&modal){modal=null;render()}});

async function init(){await initStore();ready=true;render();STORE.subscribe(async event=>{if(event.type==='recovery'){authMode='new-password';modal='auth';render();return}if(event.type==='status'){const el=$('#sync-indicator');if(el)el.textContent=syncLabel();return}if(event.type==='account'){days={};settings=structuredClone(DEFAULT_SETTINGS);conflicts=[];modal=null;page='home';authMessage='';await refreshData();render();return}if(modal||document.activeElement?.matches('input,select,textarea')){refreshPending=true;return}await refreshData();render()});if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(r=>r.update()).catch(()=>{});if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});}
init().catch(err=>{console.error(err);$('#view').innerHTML='<h2>Não foi possível iniciar o app.</h2><p>Recarregue a página e tente novamente.</p>'});
})();